}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 300px;
  padding-bottom: 24px;
}

.faq-answer p {
  font-size: 15px;
  color: var(--gray-600);
  line-height: 1.7;
}

/* Login Page */
.login-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--dark) 0%, #2D2D2D 100%);
  padding: 40px;
}

.login-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 48px;
  width: 100%;
  max-width: 440px;
  box-shadow: var(--shadow-lg);
}

.login-title {
  font-size: 32px;
  font-weight: 800;
  margin-bottom: 8px;
}

.login-subtitle {
  font-size: 15px;
  color: var(--gray-500);
  margin-bottom: 32px;
}

.social-login {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  padding: 14px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 15px;
  transition: background 0.2s;
}

.social-btn.facebook {
  background: #1877F2;
  color: var(--white);
}

.social-btn.facebook:hover { background: #166FE5; }

.social-btn.apple {
  background: var(--dark);
  color: var(--white);
}

.social-btn.apple:hover { background: #000; }

.divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 24px 0;
  color: var(--gray-400);
  font-size: 14px;
}

.divider::before, .divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--gray-200);
}

.form-group {
  margin-bottom: 20px;
}

.form-group label {
  display: block;
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 8px;
}

.form-group input {
  width: 100%;
  padding: 14px 16px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-sm);
  font-size: 15px;
  transition: border-color 0.2s;
}

.form-group input:focus {
  outline: none;
  border-color: var(--primary);
}

.password-field {
  position: relative;
}

.password-toggle {
  position: absolute;
  right: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-400);
  cursor: pointer;
}

.forgot-link {
  display: block;
  text-align: right;
  font-size: 14px;
  color: var(--primary);
  margin-bottom: 24px;
}

.login-btn {
  width: 100%;
  padding: 16px;
  background: var(--primary);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: 16px;
  transition: background 0.2s;
}

.login-btn:hover { background: var(--primary-dark); }

.login-footer {
  text-align: center;
  margin-top: 24px;
  font-size: 14px;
  color: var(--gray-500);
}

.login-footer a {
  color: var(--primary);
  font-weight: 600;
}

/* Responsive */
@media (max-width: 1024px) {
  .header { padding: 0 24px; }
  .container { padding: 0 24px; }
  .nav-links { display: none; }
  .hero-title { font-size: 40px; }
  .value-props-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .projects-gallery { grid-template-columns: repeat(3, 1fr); }
  .cert-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .hero-title { font-size: 32px; }
  .hero-subtitle { font-size: 16px; }
  .section-title { font-size: 22px; }
  .carousel-card { flex: 0 0 calc(50% - 12px); }
  .carousel-nav { display: none; }
  .courses-layout { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .projects-gallery { grid-template-columns: repeat(2, 1fr); }
  .pricing-cards { grid-template-columns: 1fr; }
  .cert-grid { grid-template-columns: 1fr; }
  .footer-grid { display: none; }
  .footer-accordion { display: block; }
  .footer-mobile-sections { display: block; }
}

@media (max-width: 480px) {
  .promo-content { flex-direction: column; gap: 8px; }
  .carousel-card { flex: 0 0 calc(100% - 48px); }
  .projects-gallery { grid-template-columns: 1fr; }
}

