/* CreativeHub Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');

:root {
  --primary: #F02D00;
  --primary-dark: #D02600;
  --dark: #171717;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --teal: #00B090;
  --teal-dark: #009078;

  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06);
  --shadow-md: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04);
  --radius: 12px;
  --radius-sm: 8px;
  --radius-lg: 16px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--white);
  color: var(--dark);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { text-decoration: none; color: inherit; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
img { max-width: 100%; display: block; }

/* Header */
.header {
  background: var(--dark);
  color: var(--white);
  padding: 0 40px;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  font-size: 24px;
  font-weight: 900;
  color: var(--primary);
  letter-spacing: -0.5px;
}

.logo span { color: var(--white); }

.nav-links {
  display: flex;
  gap: 32px;
  align-items: center;
}

.nav-links a {
  font-weight: 500;
  font-size: 15px;
  transition: color 0.2s;
}

.nav-links a:hover { color: var(--primary); }

.nav-links a.plus-link {
  background: var(--primary);
  padding: 8px 20px;
  border-radius: 24px;
  font-weight: 600;
}

.nav-links a.plus-link:hover { background: var(--primary-dark); color: var(--white); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.search-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(255,255,255,0.1);
  padding: 8px 16px;
  border-radius: 24px;
  color: rgba(255,255,255,0.7);
  font-size: 14px;
  transition: background 0.2s;
}

.search-btn:hover { background: rgba(255,255,255,0.15); color: var(--white); }

/* Promotional Banner */
.promo-banner {
  background: linear-gradient(135deg, var(--primary) 0%, #FF5740 100%);
  color: var(--white);
  padding: 12px 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  position: relative;
}

.promo-content {
  display: flex;
  align-items: center;
  gap: 24px;
  font-weight: 500;
}

.promo-content span { opacity: 0.9; }

.promo-timer {
  display: flex;
  gap: 8px;
  font-weight: 700;
}

.timer-box {
  background: rgba(0,0,0,0.2);
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 14px;
}

.promo-close {
  position: absolute;
  right: 40px;
  color: var(--white);
  opacity: 0.8;
  font-size: 20px;
  cursor: pointer;
}

.promo-close:hover { opacity: 1; }

/* Container */
.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 40px;
}

/* Section Headers */
.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 32px;
}

.section-title {
  font-size: 28px;
  font-weight: 800;
  letter-spacing: -0.5px;
}

.section-link {
  color: var(--primary);
  font-weight: 600;
  font-size: 15px;
  display: flex;
  align-items: center;
  gap: 4px;
}

.section-link:hover { text-decoration: underline; }

/* Carousel */
.carousel-section { padding: 48px 0; }

.carousel-wrapper {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: 24px;
  transition: transform 0.4s ease;
}

.carousel-card {
  flex: 0 0 calc(25% - 18px);
  background: var(--white);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: transform 0.3s, box-shadow 0.3s;
}

.carousel-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background: var(--white);
  border-radius: 50%;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  color: var(--dark);
  cursor: pointer;
  z-index: 10;
  transition: background 0.2s, transform 0.2s;
}

.carousel-nav:hover {
  background: var(--primary);
  color: var(--white);
  transform: translateY(-50%) scale(1.05);
}

.carousel-nav.prev { left: -24px; }
.carousel-nav.next { right: -24px; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-300);
  cursor: pointer;
  transition: background 0.2s, transform 0.2s;
}

.carousel-dot.active {
  background: var(--primary);
  transform: scale(1.2);
}

/* Spec Card (Hero Carousel) */
.spec-card-image {
  height: 200px;
  background: linear-gradient(135deg, var(--gray-100) 0%, var(--gray-200) 100%);
  position: relative;
  overflow: hidden;
}

.spec-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.spec-badge {
