}

.spec-card-pricing {
  display: flex;
  align-items: center;
  gap: 12px;
}

.spec-price {
  font-size: 20px;
  font-weight: 800;
  color: var(--primary);
}

.spec-original {
  font-size: 14px;
  color: var(--gray-400);
  text-decoration: line-through;
}

.spec-free-tag {
  font-size: 12px;
  color: var(--gray-500);
  background: var(--gray-100);
  padding: 4px 8px;
