}

.project-stats {
  display: flex;
  gap: 16px;
  font-size: 12px;
  color: var(--gray-500);
}

.project-stats span {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Plus Page */
.plus-hero {
  background: linear-gradient(135deg, var(--dark) 0%, #2D2D2D 100%);
  color: var(--white);
  padding: 80px 0;
  text-align: center;
}

.plus-hero-title {
  font-size: 48px;
  font-weight: 900;
  letter-spacing: -1px;
  margin-bottom: 16px;
}

.plus-hero-title span { color: var(--teal); }

.plus-hero-subtitle {
  font-size: 20px;
  color: rgba(255,255,255,0.7);
  max-width: 600px;
  margin: 0 auto 32px;
}

.plus-hero-cta {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: var(--teal);
  color: var(--white);
  padding: 16px 40px;
  border-radius: 32px;
  font-weight: 700;
  font-size: 16px;
  transition: background 0.2s;
}

.plus-hero-cta:hover { background: var(--teal-dark); }

/* Pricing Toggle */
.pricing-section {
  padding: 64px 0;
  background: var(--gray-50);
}

.pricing-toggle {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 24px;
  margin-bottom: 40px;
}

.pricing-tab {
  padding: 12px 32px;
  border-radius: 32px;
  font-size: 16px;
  font-weight: 600;
  color: var(--gray-500);
  background: transparent;
  transition: all 0.3s;
}

.pricing-tab.active {
  background: var(--dark);
  color: var(--white);
}

.pricing-save-badge {
  background: var(--primary);
  color: var(--white);
  padding: 6px 14px;
  border-radius: 16px;
  font-size: 13px;
  font-weight: 700;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
  max-width: 900px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  box-shadow: var(--shadow);
  text-align: center;
}

.pricing-card.featured {
  border: 2px solid var(--primary);
  position: relative;
}

.pricing-card.featured::before {
  content: 'BEST VALUE';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  padding: 4px 16px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 700;
}

.pricing-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-500);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 16px;
}

.pricing-amount {
  font-size: 48px;
  font-weight: 900;
  color: var(--dark);
  line-height: 1;
}

.pricing-period {
  font-size: 16px;
  color: var(--gray-500);
  font-weight: 400;
  margin-top: 8px;
}

.pricing-billed {
  font-size: 14px;
  color: var(--gray-500);
  margin-top: 8px;
}

.pricing-credits {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--teal);
  color: var(--white);
  padding: 6px 14px;
  border-radius: 16px;
  font-size: 13px;
  font-weight: 600;
  margin-top: 16px;
}

.pricing-cta {
  display: block;
  width: 100%;
  padding: 16px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: 16px;
  margin-top: 24px;
  transition: background 0.2s;
}

.pricing-cta.primary {
  background: var(--primary);
  color: var(--white);
}

.pricing-cta.primary:hover { background: var(--primary-dark); }

.pricing-cta.secondary {
  background: var(--gray-100);
  color: var(--dark);
}

.pricing-cta.secondary:hover { background: var(--gray-200); }

/* Credits Features */
.credits-section { padding: 64px 0; }

.credits-carousel {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  padding-bottom: 24px;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}

.credits-carousel::-webkit-scrollbar { display: none; }

.credit-card {
  flex: 0 0 300px;
  background: var(--white);
  border-radius: var(--radius);
  padding: 32px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  scroll-snap-align: start;
}

.credit-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--primary) 0%, #FF5740 100%);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 20px;
}

.credit-title {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 8px;
}

.credit-desc {
  font-size: 14px;
  color: var(--gray-500);
  line-height: 1.6;
}

/* Certificates Section */
.certificates-section {
  padding: 64px 0;
  background: var(--gray-50);
}

.cert-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.cert-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 32px;
  box-shadow: var(--shadow-sm);
  text-align: center;
}

.cert-icon {
  font-size: 48px;
  margin-bottom: 16px;
}

.cert-title {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 8px;
}

.cert-desc {
  font-size: 14px;
  color: var(--gray-500);
}

/* FAQ Accordion */
.faq-section { padding: 64px 0; }

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  font-size: 18px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
}

.faq-question::after {
  content: '+';
  font-size: 24px;
  font-weight: 300;
  color: var(--gray-400);
  transition: transform 0.3s;
}

.faq-item.active .faq-question::after {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 300px;
  padding-bottom: 24px;
}

.faq-answer p {
  font-size: 15px;
  color: var(--gray-600);
  line-height: 1.7;
}

/* Login Page */
.login-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--dark) 0%, #2D2D2D 100%);
  padding: 40px;
}

.login-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 48px;
  width: 100%;
  max-width: 440px;
  box-shadow: var(--shadow-lg);
}

.login-title {
  font-size: 32px;
  font-weight: 800;
  margin-bottom: 8px;
}

.login-subtitle {
  font-size: 15px;
  color: var(--gray-500);
  margin-bottom: 32px;
}

.social-login {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  padding: 14px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 15px;
  transition: background 0.2s;
}

.social-btn.facebook {
  background: #1877F2;
  color: var(--white);
}

.social-btn.facebook:hover { background: #166FE5; }

.social-btn.apple {
  background: var(--dark);
  color: var(--white);
}

.social-btn.apple:hover { background: #000; }

.divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 24px 0;
  color: var(--gray-400);
  font-size: 14px;
}

.divider::before, .divider::after {
  content: '';
